import{_ as a,o,c as i,a2 as r}from"./chunks/framework.D7Ov6LBE.js";const p=JSON.parse('{"title":"08 — Sincronização Offline","description":"","frontmatter":{},"headers":[],"relativePath":"docs-legados/08-sincronizacao.md","filePath":"docs-legados/08-sincronizacao.md","lastUpdated":1786474711000}'),t={name:"docs-legados/08-sincronizacao.md"};function n(d,e,s,l,c,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="_08-—-sincronizacao-offline" tabindex="-1">08 — Sincronização Offline <a class="header-anchor" href="#_08-—-sincronizacao-offline" aria-label="Permalink to &quot;08 — Sincronização Offline&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Documento original</p><p>Conteúdo integral preservado de <code>docs/08-estrategia-sincronizacao-offline.md</code>. Parte da wiki para manter a rastreabilidade com a documentação histórica do projeto.</p></div><h2 id="_1-visao-geral" tabindex="-1">1. Visão Geral <a class="header-anchor" href="#_1-visao-geral" aria-label="Permalink to &quot;1. Visão Geral&quot;">​</a></h2><p>Como parte da filosofia de engenharia orientada aos negócios da Axio, o ERP Ampla Vendas opera primordialmente de forma <strong>Offline-First</strong>. Isso garante que vendedores e representantes possam continuar faturando e emitindo pedidos mesmo em regiões sem conectividade (0% de sinal 4G/Wi-Fi).</p><p>Esta abordagem introduz complexidade arquitetural que foi calculada e justificada pela disponibilidade ininterrupta das operações comerciais.</p><h2 id="_2-padrao-outbox-e-conexao-zero" tabindex="-1">2. Padrão Outbox e Conexão Zero <a class="header-anchor" href="#_2-padrao-outbox-e-conexao-zero" aria-label="Permalink to &quot;2. Padrão Outbox e Conexão Zero&quot;">​</a></h2><p>Para mitigar a complexidade de requisições HTTP falhas quando não há conexão:</p><ul><li><strong>Zero Conexão:</strong> Quando o usuário está offline, não disparamos requests HTTP diretos que fatalmente falhariam (gerando unhandled rejections).</li><li><strong>Padrão Outbox (Caixa de Saída):</strong> Toda &quot;mutação&quot; (ex: criar pedido, atualizar cliente) é interceptada pela camada de serviço e gravada localmente (IndexedDB via Dexie.js) em uma fila cronológica (<code>outbox_sync_queue</code>).</li><li><strong>Sync em Background:</strong> Um <code>Service Worker</code> ou um loop de checagem de conectividade observa o estado da rede. Assim que a conexão é restaurada, a fila é processada sequencialmente, garantindo a consistência das transações no backend.</li></ul><h2 id="_3-empacotamento-do-estado-local-cache" tabindex="-1">3. Empacotamento do Estado Local (Cache) <a class="header-anchor" href="#_3-empacotamento-do-estado-local-cache" aria-label="Permalink to &quot;3. Empacotamento do Estado Local (Cache)&quot;">​</a></h2><p>A operação offline exige um repositório de dados cliente.</p><ul><li>O cache não é apenas para leitura rápida (como o cache do navegador tradicional), mas um <strong>banco de dados relacional embarcado no browser</strong> (IndexedDB abstrato pelo Dexie.js).</li><li><strong>Snapshot Local:</strong> Durante o primeiro login ou sincronização de &quot;bom dia&quot;, o app faz o download (paginado/compactado) do catálogo de produtos, tabela de preços e carteira de clientes, empacotando o &quot;Estado Offline&quot;.</li></ul><h2 id="_4-resolucao-de-conflitos-event-sourcing-timeline" tabindex="-1">4. Resolução de Conflitos (Event Sourcing &amp; Timeline) <a class="header-anchor" href="#_4-resolucao-de-conflitos-event-sourcing-timeline" aria-label="Permalink to &quot;4. Resolução de Conflitos (Event Sourcing &amp; Timeline)&quot;">​</a></h2><p>Operações distribuídas podem gerar &quot;colisões&quot;, análogas ao <code>git cherry-pick</code> ou <code>merge conflict</code>.</p><ul><li><strong>Decisões &quot;Forkadas&quot;:</strong> Se dois vendedores offline atualizam o mesmo registro (ex: alteram o telefone de um cliente), cada um cria um fork temporário em suas timelines locais.</li><li><strong>Tipos de Colisão:</strong><ul><li><strong>Soft (Cadastros/Metadados):</strong> Resolução baseada em <em>Last-Write-Wins</em> (Última gravação vence), calculada com base no timestamp da mutação local.</li><li><strong>Hard (Estoque/Financeiro):</strong> Em vez de sobrescrever o saldo (ex: estoque local = 5), gravamos a <strong>Intenção/Evento</strong> (ex: <code>-1 item A</code>). Ao chegar no servidor, o evento é aplicado na timeline real. Se o saldo servidor já for insuficiente (estoque = 0), a operação entra em estado de &quot;Alerta/Pendente&quot; para aprovação gerencial, não abortando silenciosamente a venda, mas garantindo que o furo de estoque seja tratado.</li></ul></li><li>Isso é conhecido como modelagem de <em>Timeline Baseada em Eventos</em>, essencial para a arquitetura de sincronização do Axio.</li></ul><h2 id="_5-reversibilidade-e-flexibilidade-cloud-only" tabindex="-1">5. Reversibilidade e Flexibilidade (Cloud-Only) <a class="header-anchor" href="#_5-reversibilidade-e-flexibilidade-cloud-only" aria-label="Permalink to &quot;5. Reversibilidade e Flexibilidade (Cloud-Only)&quot;">​</a></h2><p>Se os requisitos de negócios mudarem no futuro e a exigência de &quot;local-first&quot; for descartada em favor de uma versão estritamente online:</p><ul><li>A arquitetura está preparada para uma <strong>migração de baixo esforço</strong> (Patch/Bypass).</li><li>Como as regras de negócio e a interface não sabem que o Dexie existe (elas conversam com um &quot;Adapter/Repository&quot; de dados), basta trocar a injeção de dependência do <code>OfflineRepository</code> para um <code>CloudRepository</code> (que faz o request HTTP direto para o Supabase/Edge Functions).</li><li>A base de UI (React) e regras de estado global (Zustand) permaneceriam 100% inalteradas.</li></ul><hr><p><em>Assinado:</em><strong>Engenheiro Chefe &amp; Especialista de Implementação, Axio Engineering</strong></p>',19)])])}const g=a(t,[["render",n]]);export{p as __pageData,g as default};
